// Parse Vapi tool-call + validate booking rules (Europe/Berlin).
const SECRET = '__VAPI_WEBHOOK_SECRET__';
const w = $input.first().json;
const hdrs = w.headers || {};
if (String(hdrs['x-vapi-secret'] || '') !== SECRET) {
  return [{ json: { action: 'error', toolCallId: 'unauthorized',
            result: 'Interner Fehler: nicht autorisiert.' } }];
}
const msg = (w.body && w.body.message) || {};
const tc = (msg.toolCallList && msg.toolCallList[0]) || {};
const toolCallId = tc.id || '';
const fname = (tc.function && tc.function.name) || tc.name || '';
let args = (tc.function && tc.function.arguments) || tc.arguments || {};
if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }

const fail = (text) => [{ json: { action: 'error', toolCallId, result: text } }];
if (msg.type !== 'tool-calls' || !toolCallId) return fail('Interner Fehler: unerwartetes Ereignis.');
if (fname !== 'check_availability' && fname !== 'book_appointment')
  return fail('Interner Fehler: unbekannte Funktion.');

// --- Berlin time helpers (no external deps) ---
const berlinFmt = new Intl.DateTimeFormat('de-DE', { timeZone: 'Europe/Berlin',
  weekday: 'short', year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', hour12: false });
const parts = (d) => Object.fromEntries(berlinFmt.formatToParts(d).map(p => [p.type, p.value]));

let raw = String(args.startzeit || '').trim();
if (!raw) return fail('Es fehlt die gewuenschte Uhrzeit.');
let start;
if (/[+-]\d\d:?\d\d$|Z$/.test(raw)) {
  start = new Date(raw);
} else {
  // no offset given -> interpret as Berlin wall-clock: pick the offset that round-trips
  for (const off of ['+02:00', '+01:00']) {
    const cand = new Date(raw + off);
    if (isNaN(cand)) continue;
    const p = parts(cand);
    const rt = `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}`;
    if (raw.startsWith(rt.slice(0, raw.length))) { start = cand; break; }
    start = start || cand;
  }
}
if (!start || isNaN(start)) return fail('Die Uhrzeit war nicht verstaendlich. Bitte nochmal nach Datum und Uhrzeit fragen.');

const durMin = Math.min(Math.max(parseInt(args.dauer_minuten) || 30, 15), 60);
const end = new Date(start.getTime() + durMin * 60000);
const now = new Date();

if (start.getTime() < now.getTime() + 2 * 3600 * 1000)
  return fail('Dieser Termin liegt zu kurzfristig oder in der Vergangenheit. Der frueheste Termin ist in etwa zwei Stunden.');
if (start.getTime() > now.getTime() + 30 * 86400 * 1000)
  return fail('So weit im Voraus buchen wir noch nicht. Bitte einen Termin innerhalb der naechsten vier Wochen vorschlagen.');

const p = parts(start), pe = parts(end);
if (String(p.weekday).startsWith('Sa') || String(p.weekday).startsWith('So'))
  return fail('Am Wochenende ist Erwin nicht erreichbar. Bitte einen Werktag vorschlagen.');
const startHM = parseInt(p.hour) * 60 + parseInt(p.minute);
const endHM = parseInt(pe.hour) * 60 + parseInt(pe.minute);
if (startHM < 10 * 60 || endHM > 16 * 60 + 45 || endHM <= startHM)
  return fail('Erwin ist werktags zwischen zehn Uhr und viertel vor fuenf erreichbar. Bitte eine Uhrzeit in diesem Fenster vorschlagen.');

const spokenFmt = new Intl.DateTimeFormat('de-DE', { timeZone: 'Europe/Berlin',
  weekday: 'long', day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit' });
const clean = (v) => String(v == null ? '' : v).slice(0, 200);

return [{ json: {
  action: fname === 'check_availability' ? 'check' : 'book',
  toolCallId,
  startISO: start.toISOString(), endISO: end.toISOString(),
  bufStartISO: new Date(start.getTime() - 15 * 60000).toISOString(),
  bufEndISO: new Date(end.getTime() + 15 * 60000).toISOString(),
  spoken: spokenFmt.format(start) + ' Uhr',
  name: clean(args.name), firma: clean(args.firma), telefon: clean(args.telefon),
  email: clean(args.email), thema: clean(args.thema),
} }];

// freeBusy result -> frei/nicht frei. Only busy intervals ever reach this point.
const ctx = $('Parse + Pruefen').first().json;
const fb = $input.first().json;
const busy = ((fb.calendars || {})['__GOOGLE_CALENDAR_ID__'] || {}).busy || [];
const available = busy.length === 0;
let result;
if (ctx.action === 'check') {
  result = available
    ? `FREI: ${ctx.spoken} ist verfuegbar. Bei Zusage direkt mit book_appointment buchen.`
    : `NICHT FREI: ${ctx.spoken} ist leider schon verplant. Bitte einen anderen Vorschlag erfragen. Keine Details nennen.`;
} else {
  result = available ? '' : `NICHT FREI: ${ctx.spoken} ist inzwischen verplant. Bitte einen anderen Vorschlag erfragen.`;
}
return [{ json: { ...ctx, available, result } }];

